def is_perfect_square(n: int) -> bool:
    """Check if n is a perfect square using Newton's method (integer-only)."""
    if n < 0:
        return False
    if n == 0:
        return True

    # Initial estimate: start with n itself, then converge
    x = n
    while x * x > n:
        x = (x + n // x) // 2

    return x * x == n


def is_perfect_square_binary(n: int) -> bool:
    """Check if n is a perfect square using binary search."""
    if n < 0:
        return False
    if n == 0:
        return True

    lo, hi = 1, n
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1

    return False


if __name__ == "__main__":
    test_cases = [
        0, 1, 2, 3, 4, 9, 15, 16, 25, 26, 100, 144,
        10**12, 10**12 + 1, 2**60, 2**60 - 1, -4, -1,
    ]

    print(f"{'n':>20}  {'Newton':>7}  {'Binary':>7}")
    print("-" * 40)
    for n in test_cases:
        r1 = is_perfect_square(n)
        r2 = is_perfect_square_binary(n)
        match = "✓" if r1 == r2 else "MISMATCH"
        print(f"{n:>20}  {str(r1):>7}  {str(r2):>7}  {match}")
